div.script:
//
(function(){
var URL="https://gkqyaroprqajwoubnsvs.supabase.co",KEY="sb_publishable_R7vD8tuifiaNOAhOSQdAyw_Ie4OHa7f",db=window.supabase.createClient(URL,KEY),user=null,signup=false;
function $(x){return document.getElementById(x)}function esc(x){return String(x==null?"":x).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#039;")}function toast(x){$("toast").textContent=x;$("toast").classList.add("show");setTimeout(function(){$("toast").classList.remove("show")},2500)}
function auth(){ $("auth").style.display="flex";$("app").style.display="none"}function app(){ $("auth").style.display="none";$("app").style.display="block"}
async function profile(){if(!user)return;var r=await db.from("profiles").select("username,full_name,bio,avatar_url").eq("id",user.id).maybeSingle(),p=r.data||{};$("profileBox").innerHTML='<div class="avatar">'+esc((p.full_name||p.username||"U").slice(0,1).toUpperCase())+'</div><h2>'+esc(p.full_name||p.username||"User")+'</h2><div class="muted">'+esc(p.username?"@"+p.username:"")+'</div><p>'+esc(p.bio||"")+'</p>'}
async function feed(){var b=$("feedBox");b.innerHTML='<div class="empty">Loading...</div>';var r=await db.from("posts").select("id,user_id,content,image_url,video_url,privacy,created_at,profiles(username,full_name,avatar_url)").eq("privacy","public").order("created_at",{ascending:false}).limit(30);if(r.error){b.innerHTML='<div class="empty">'+esc(r.error.message)+'</div>';return}var a=r.data||[];if(!a.length){b.innerHTML='<div class="empty">No public SocialHub posts yet.</div>';return}b.innerHTML=a.map(function(p){var u=p.profiles||{},n=u.full_name||u.username||"User",m=p.image_url?'<img class="media" src="'+esc(p.image_url)+'"/>':(p.video_url?'<video class="media" controls src="'+esc(p.video_url)+'"></video>':"");return '<article class="card"><div class="posthead"><div class="avatar">'+esc(n[0].toUpperCase())+'</div><div><b>'+esc(n)+'</b><div class="muted">'+esc(p.created_at||"")+'</div></div></div><div class="content">'+esc(p.content||"")+'</div>'+m+'<div class="actions"><button data-like="'+esc(p.id)+'" type="button">❤️ Like</button></div></article>'}).join("")}
async function post(){if(!user){toast("Log in first");return}var t=$("postText").value.trim();if(!t){toast("Write something first");return}var r=await db.from("posts").insert({user_id:user.id,content:t,privacy:"public"});if(r.error){toast(r.error.message);return}$("postText").value="";toast("Posted to SocialHub");feed()}
async function login(){var r=await db.auth.signInWithPassword({email:$("email").value.trim(),password:$("password").value});if(r.error){toast(r.error.message);return}user=r.data.user;app();profile();feed()}
async function register(){var n=$("name").value.trim(),e=$("email").value.trim(),p=$("password").value;if(!n||!e||!p){toast("Complete all fields");return}var u=n.toLowerCase().replace(/[^a-z0-9]+/g,"_").replace(/^_+|_+$/g,"").slice(0,30)||("user_"+Date.now()),r=await db.auth.signUp({email:e,password:p,options:{data:{full_name:n,username:u}}});if(r.error){toast(r.error.message);return}if(r.data.session){user=r.data.user;app();profile();feed()}else toast("Account created. Check your email if confirmation is enabled.")}
async function logout(){await db.auth.signOut();user=null;auth()}
async function search(){var q=$("search").value.trim();if(q.length<2){$("results").textContent="Search for people above.";return}var r=await db.from("profiles").select("username,full_name").or("username.ilike.%"+q+"%,full_name.ilike.%"+q+"%").limit(10);if(r.error){$("results").textContent=r.error.message;return}$("results").innerHTML=(r.data||[]).map(function(x){return '<div style="padding:9px 0;border-bottom:1px solid #eee"><b>'+esc(x.full_name||x.username)+'</b><div class="muted">@'+esc(x.username||"")+'</div></div>'}).join("")||"No users found."}
async function saved(){var b=$("savedBox"),r=await db.from("saved_posts").select("post_id,posts(content,created_at)").eq("user_id",user.id);if(r.error){b.textContent=r.error.message;return}b.innerHTML=(r.data||[]).map(function(x){return '<div style="padding:12px 0;border-bottom:1px solid #eee">'+esc(x.posts&&x.posts.content||"")+'</div>'}).join("")||"No saved posts yet."}
async function notes(){var b=$("notificationsBox"),r=await db.from("notifications").select("*").eq("user_id",user.id).order("created_at",{ascending:false}).limit(30);if(r.error){b.textContent=r.error.message;return}b.innerHTML=(r.data||[]).map(function(x){return '<div style="padding:10px 0;border-bottom:1px solid #eee">'+esc(x.message||x.type||"Notification")+'</div>'}).join("")||"No notifications yet."}
async function messages(){var b=$("messagesBox"),r=await db.from("conversation_members").select("conversation_id").eq("user_id",user.id);if(r.error){b.textContent=r.error.message;return}b.innerHTML=(r.data||[]).map(function(x){return '<div style="padding:10px 0">Conversation '+esc(x.conversation_id)+'</div>'}).join("")||"No conversations yet."}
function view(v){document.querySelectorAll(".view").forEach(function(x){x.classList.remove("active")});$(v).classList.add("active");document.querySelectorAll("[data-view]").forEach(function(x){x.classList.toggle("active",x.getAttribute("data-view")===v)});if(v==="feed")feed();if(v==="profile")profile();if(v==="saved")saved();if(v==="notifications")notes();if(v==="messages")messages()}
document.addEventListener("DOMContentLoaded",function(){
$("submit").onclick=function(){signup?register():login()};$("switch").onclick=function(){signup=!signup;$("name").style.display=signup?"block":"none";$("submit").textContent=signup?"Create account":"Login";$("switchText").textContent=signup?"Already have an account?":"Don't have an account?";$("switch").textContent=signup?" Login":" Sign up"};$("logout").onclick=logout;$("post").onclick=post;$("search").oninput=function(){clearTimeout(window.sht);window.sht=setTimeout(search,300)};document.querySelectorAll("[data-view]").forEach(function(x){x.onclick=function(){view(x.getAttribute("data-view"))}});
db.auth.getSession().then(function(r){user=r.data.session?r.data.session.user:null;if(user){app();profile();feed()}else auth()});db.auth.onAuthStateChange(function(e,s){user=s?s.user:null;if(user){app();profile();feed()}else auth()})
})
})();
//
